const salida = $input.first()?.json ?? {};

const entrada =
  $('recibir_operacion_estado_conversacion_dz')
    .first()
    .json;

if (
  salida.chatwoot_id === undefined ||
  salida.chatwoot_id === null
) {
  throw new Error(
    'DZ_ESTADO_CONVERSACION_NO_ENCONTRADO'
  );
}

if (salida.estado_sofia !== 'transferencia_activa') {
  throw new Error(
    'DZ_TRANSFERENCIA_NO_PERSISTIDA'
  );
}

if (
  salida.motivo_transferencia !==
  entrada.motivo_transferencia
) {
  throw new Error(
    'DZ_MOTIVO_TRANSFERENCIA_NO_PERSISTIDO'
  );
}

return [{ json: salida }];

const salida = $input.first()?.json ?? {};

const entrada =
  $('serializar_contexto_proceso_dz')
    .first()
    .json;

function normalizarObjeto(valor) {
  if (Array.isArray(valor)) {
    return valor.map(normalizarObjeto);
  }

  if (
    valor !== null &&
    typeof valor === 'object'
  ) {
    return Object.keys(valor)
      .sort()
      .reduce((resultado, clave) => {
        resultado[clave] =
          normalizarObjeto(valor[clave]);

        return resultado;
      }, {});
  }

  return valor;
}

if (
  Number(salida.chatwoot_id) !==
  Number(entrada.chatwoot_id)
) {
  throw new Error(
    'DZ_ACTUALIZACION_PROCESO_NO_APLICADA'
  );
}

if (
  Number(salida.ultimo_message_id) !==
  Number(entrada.ultimo_message_id)
) {
  throw new Error(
    'DZ_ACTUALIZACION_PROCESO_MESSAGE_ID_OBSOLETO'
  );
}

if (
  salida.proceso_activo !==
  entrada.proceso_activo
) {
  throw new Error(
    'DZ_ACTUALIZACION_PROCESO_INCONSISTENTE'
  );
}

if (
  salida.paso_activo !==
  entrada.paso_activo
) {
  throw new Error(
    'DZ_ACTUALIZACION_PASO_INCONSISTENTE'
  );
}

const contextoGuardado = JSON.stringify(
  normalizarObjeto(salida.contexto)
);

const contextoSolicitado = JSON.stringify(
  normalizarObjeto(
    JSON.parse(entrada.contexto_json)
  )
);

if (contextoGuardado !== contextoSolicitado) {
  throw new Error(
    'DZ_ACTUALIZACION_CONTEXTO_INCONSISTENTE'
  );
}

if (
  !Number.isSafeInteger(Number(salida.version)) ||
  Number(salida.version) <= 0
) {
  throw new Error(
    'DZ_ACTUALIZACION_PROCESO_VERSION_INVALIDA'
  );
}

return [{ json: salida }];

const entrada = $input.first()?.json ?? {};

function normalizarEstadoProceso(
  valor,
  codigoError
) {
  if (
    valor === null ||
    valor === undefined
  ) {
    return null;
  }

  if (typeof valor !== 'string') {
    throw new Error(codigoError);
  }

  const valorNormalizado = valor.trim();

  return valorNormalizado === ''
    ? null
    : valorNormalizado;
}

if (
  typeof entrada.contexto_json !== 'string' ||
  entrada.contexto_json.trim() === ''
) {
  throw new Error(
    'DZ_CONTEXTO_PROCESO_JSON_AUSENTE'
  );
}

let contexto;

try {
  contexto = JSON.parse(
    entrada.contexto_json
  );
} catch {
  throw new Error(
    'DZ_CONTEXTO_PROCESO_JSON_INVALIDO'
  );
}

if (
  contexto === null ||
  Array.isArray(contexto) ||
  typeof contexto !== 'object'
) {
  throw new Error(
    'DZ_CONTEXTO_PROCESO_INVALIDO'
  );
}

const proceso_activo =
  normalizarEstadoProceso(
    entrada.proceso_activo,
    'DZ_PROCESO_ACTIVO_INVALIDO'
  );

const paso_activo =
  normalizarEstadoProceso(
    entrada.paso_activo,
    'DZ_PASO_ACTIVO_INVALIDO'
  );

return [
  {
    json: {
      ...entrada,
      proceso_activo,
      paso_activo,
      contexto,
      contexto_json:
        JSON.stringify(contexto),
    },
  },
];

const entrada = $input.first()?.json ?? {};

if (
  entrada.accion !==
  'abrir_confirmacion_cita'
) {
  throw new Error(
    'DZ_APERTURA_CONFIRMACION_ACCION_INVALIDA'
  );
}

if (
  !Number.isSafeInteger(
    Number(entrada.chatwoot_id)
  ) ||
  Number(entrada.chatwoot_id) <= 0
) {
  throw new Error(
    'DZ_APERTURA_CONFIRMACION_CHATWOOT_ID_INVALIDO'
  );
}

if (
  typeof entrada.conversation_id !== 'string' ||
  entrada.conversation_id.trim() === ''
) {
  throw new Error(
    'DZ_APERTURA_CONFIRMACION_CONVERSATION_ID_INVALIDO'
  );
}

if (
  entrada.proceso_activo !== 'gestion_cita'
) {
  throw new Error(
    'DZ_APERTURA_CONFIRMACION_PROCESO_INVALIDO'
  );
}

if (
  entrada.paso_activo !==
  'confirmar_cita_paciente'
) {
  throw new Error(
    'DZ_APERTURA_CONFIRMACION_PASO_INVALIDO'
  );
}

const contexto = entrada.context;

if (
  contexto === null ||
  Array.isArray(contexto) ||
  typeof contexto !== 'object'
) {
  throw new Error(
    'DZ_APERTURA_CONFIRMACION_CONTEXTO_INVALIDO'
  );
}

const gestionCita =
  contexto.gestion_cita;

if (
  gestionCita === null ||
  Array.isArray(gestionCita) ||
  typeof gestionCita !== 'object'
) {
  throw new Error(
    'DZ_APERTURA_CONFIRMACION_GESTION_CITA_INVALIDA'
  );
}

if (
  gestionCita.origen !==
  'confirmacion_cita'
) {
  throw new Error(
    'DZ_APERTURA_CONFIRMACION_ORIGEN_INVALIDO'
  );
}

if (
  typeof gestionCita.cita_id !== 'string' ||
  gestionCita.cita_id.trim() === ''
) {
  throw new Error(
    'DZ_APERTURA_CONFIRMACION_CITA_ID_INVALIDO'
  );
}

if (
  gestionCita.estado_confirmacion !==
  'solicitada'
) {
  throw new Error(
    'DZ_APERTURA_CONFIRMACION_ESTADO_INVALIDO'
  );
}

return [
  {
    json: {
      ...entrada,
      chatwoot_id:
        Number(entrada.chatwoot_id),
      conversation_id:
        entrada.conversation_id.trim(),
      contexto,
      contexto_json:
        JSON.stringify(contexto),
    },
  },
];

const salida = $input.first()?.json ?? {};

const entrada =
  $('validar_apertura_confirmacion_cita_dz')
    .first()
    .json;

function normalizarObjeto(valor) {
  if (Array.isArray(valor)) {
    return valor.map(normalizarObjeto);
  }

  if (
    valor !== null &&
    typeof valor === 'object'
  ) {
    return Object.keys(valor)
      .sort()
      .reduce((resultado, clave) => {
        resultado[clave] =
          normalizarObjeto(valor[clave]);

        return resultado;
      }, {});
  }

  return valor;
}

if (
  Number(salida.chatwoot_id) !==
  Number(entrada.chatwoot_id)
) {
  throw new Error(
    'DZ_APERTURA_CONFIRMACION_NO_APLICADA'
  );
}

if (
  salida.conversation_id !==
  entrada.conversation_id
) {
  throw new Error(
    'DZ_APERTURA_CONFIRMACION_CONVERSACION_INCONSISTENTE'
  );
}

if (
  salida.proceso_activo !==
  entrada.proceso_activo
) {
  throw new Error(
    'DZ_APERTURA_CONFIRMACION_PROCESO_INCONSISTENTE'
  );
}

if (
  salida.paso_activo !==
  entrada.paso_activo
) {
  throw new Error(
    'DZ_APERTURA_CONFIRMACION_PASO_INCONSISTENTE'
  );
}

const contextoGuardado =
  JSON.stringify(
    normalizarObjeto(salida.contexto)
  );

const contextoSolicitado =
  JSON.stringify(
    normalizarObjeto(entrada.contexto)
  );

if (
  contextoGuardado !==
  contextoSolicitado
) {
  throw new Error(
    'DZ_APERTURA_CONFIRMACION_CONTEXTO_INCONSISTENTE'
  );
}

if (
  !Number.isSafeInteger(
    Number(salida.version)
  ) ||
  Number(salida.version) <= 0
) {
  throw new Error(
    'DZ_APERTURA_CONFIRMACION_VERSION_INVALIDA'
  );
}

return [
  {
    json: salida,
  },
];
